mod outer {
    fn secret() -> u32 {
        42
    }

    pub fn reveal() -> u32 {
        secret()
    }

    pub mod inner {
        pub fn peek() -> u32 {
            // a nested module may use its parent's private items
            super::secret() + 1
        }
    }
}

fn main() {
    println!("{} {}", outer::reveal(), outer::inner::peek());
}

// Output:
// 42 43

mod bank {
    pub struct Account {
        pub owner: String,
        balance: i64,
    }

    impl Account {
        pub fn new(owner: &str) -> Account {
            Account { owner: String::from(owner), balance: 0 }
        }

        pub fn deposit(&mut self, amount: i64) {
            self.balance += amount;
        }

        pub fn balance(&self) -> i64 {
            self.balance
        }
    }
}

fn main() {
    let mut acc = bank::Account::new("Ada");
    acc.deposit(40);
    println!("{} has {}", acc.owner, acc.balance());
}

// Output:
// Ada has 40

mod zoo {
    pub mod animals {
        pub fn cat() -> String {
            String::from("meow")
        }
    }

    pub mod show {
        use super::animals;   // a use outside the module does not reach in here

        pub fn line() -> String {
            format!("the cat says {}", animals::cat())
        }
    }
}

use zoo::show;

fn main() {
    println!("{}", show::line());
}

// Output:
// the cat says meow

use std::fmt::Result as FmtResult;
use std::io::Result as IoResult;

fn check_fmt() -> FmtResult {
    Ok(())
}

