mod bank {
    pub struct Account {
        pub owner: String,
        balance: i64,
    }

    impl Account {
        pub fn new(owner: &str) -> Account {
            Account { owner: String::from(owner), balance: 0 }
        }

        pub fn deposit(&mut self, amount: i64) {
            self.balance += amount;
        }

        pub fn balance(&self) -> i64 {
            self.balance
        }

        pub fn withdraw(&mut self, amount: i64) {
            self.balance -= amount;
        }
    }
}

use bank::Account;

fn main() {
    let mut acc = Account::new("Ada");
    acc.deposit(40);
    acc.withdraw(10);
    println!("{}: {}", acc.owner, acc.balance());
}
